static QByteArray read(const QString &path){QFile f(path);require(f.open(QIODevice::ReadOnly),"VNB alias artifact missing");return f.readAll();}
static void write(const QString &path,const QByteArray &bytes){QFile f(path);require(f.open(QIODevice::WriteOnly)&&f.write(bytes)==bytes.size(),"VNB alias artifact write failed");}
using V=std::array<double,3>;using State=std::array<double,6>;
// Reuse the three prescribed state/impulse inputs and independent vector
// definitions from NasaImpulsiveFrameTests; do not call GMAT frame converters.
static const std::array<State,3> states{{{7000,-1200,900,1.5,6.75,-2},{5100,4000,-1800,-4,5,1.25},{-3300,6100,2600,-6,-2,1}}};
static const std::array<V,3> impulses{{{.01,.02,-.03},{-.02,.01,.04},{0,.03,.02}}};
static V cross(const V&a,const V&b){return {a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};}
static V unit(V a){double n=0;for(auto x:a)n+=x*x;n=std::sqrt(n);require(n>1e-12,"VNB alias independent frame degenerate");for(auto &x:a)x/=n;return a;}
static QJsonArray json(const V&a){return {a[0],a[1],a[2]};}
